// Calculate the date range for the past 7 days
const now = new Date();
const sevenDaysAgo = new Date(now);
sevenDaysAgo.setDate(now.getDate() - 7);

const fmt = (d) => d.toISOString().split('T')[0];

return {
  dateFrom: fmt(sevenDaysAgo),
  dateTo: fmt(now),
  owner: $('📋 Config').first().json.GITHUB_OWNER,
  repo: $('📋 Config').first().json.GITHUB_REPO,
  discordWebhook: $('📋 Config').first().json.DISCORD_WEBHOOK,
  language: $('📋 Config').first().json.LANGUAGE
};

