sevenDaysAgo.setDate(now.getDate() - 7);

const fmt = (d) => d.toISOString().split('T')[0];

return [{ json: {
  dateFrom: fmt(sevenDaysAgo),
  dateTo: fmt(now),
  owner: $('📋 Config').first().json.GITHUB_OWNER,
  repo: $('📋 Config').first().json.GITHUB_REPO,
  discordWebhook: $('📋 Config').first().json.DISCORD_WEBHOOK,
  language: $('📋 Config').first().json.LANGUAGE
} }];

const dateCalc = $('🗓️ Date Calculator').first().json;
const prs = $('🔀 Get Merged PRs').first().json.items || [];
const issues = $('🐛 Get Closed Issues').first().json.items || [];

const lang = dateCalc.language || 'EN';

const prList = prs.map(p => `- [${p.title}](${p.html_url}) by @${p.user.login}`).join('\n') || '(none)';
const issueList = issues.map(i => `- [${i.title}](${i.html_url}) by @${i.user.login}`).join('\n') || '(none)';

const langPrompt = lang === 'FR'
  ? 'Réponds entièrement en français.'
  : 'Respond entirely in English.';

const prompt = `${langPrompt}

You are a senior engineering manager. Write a concise but engaging weekly development summary for the repository "${dateCalc.owner}/${dateCalc.repo}" covering the period from ${dateCalc.dateFrom} to ${dateCalc.dateTo}.

Write in a professional but approachable tone. Use this data:

## Merged Pull Requests (${prs.length})
${prList}

## Closed Issues (${issues.length})
${issueList}

Write a 3-4 paragraph narrative summary. Highlight key themes, achievements, and any notable contributors. End with a one-line motivational message for the team.`;

return {
  prompt,
  owner: dateCalc.owner,
  repo: dateCalc.repo,
  discordWebhook: dateCalc.discordWebhook,
  dateFrom: dateCalc.dateFrom,
  dateTo: dateCalc.dateTo
};

